"""Persist verified live evidence and same-epoch comparisons; no remote mutations."""
from pathlib import Path
import base64,copy,hashlib,json
ROOT=Path.cwd()
MAIN=ROOT/'outputs/stem_component12_20261011_v1'
REF=ROOT/'outputs/native_stem_scratch12_20261011_v3'
PHASE=ROOT/'outputs/stem_training_phase_audit_20261011_v1'
FULL=ROOT/'outputs/original_stem12_20261011_v1'
read=lambda p:json.loads(Path(p).read_bytes())
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
bundle=json.loads(r'''{"reference":{"1":{"base64":"","expected_sha256":"0eabbe1ac292c846fccf490f7f8674c1bb60d6f3b27ec9c07302225ad15cea86","expected_bytes":3041},"2":{"base64":"","expected_sha256":"ad7e593c8e838b2ed566fc4f178d7a9b8e6fa3ba9ece13ff428c9b80ab03302b","expected_bytes":3048}},"phase":{"1":{"base64":"","sha256":"08f7b2bc20522ad03a3cd46e41c0e05d6cfbff3111bc897aaa47cc6b664898d6","bytes":1780},"2":{"base64":"","sha256":"253a275f774ea6765038a37eae0b5dec4a473a743c04ef21a6f63de05b60af05","bytes":1780}}}''')
def write(p,x):
    with Path(p).open('x',encoding='utf8') as f:
        json.dump(x,f,ensure_ascii=False,indent=2,allow_nan=False)
snapfile=MAIN/'training_observation_v25.json'
snap=read(snapfile)
assert sha(snapfile)==read(MAIN/'training_observation_v25_transport_verification.json')['verified_snapshot_sha256']
refs={};reftransport={};phases={};phasetransport={}
for seed in (1,2):
    d=bundle['reference'][str(seed)]
    raw=base64.b64decode(d['base64'],validate=True)
    assert len(raw)==d['expected_bytes'] and hashlib.sha256(raw).hexdigest()==d['expected_sha256']
    o=json.loads(raw)
    assert o['seed']==seed and o['code_sha256_verified'] and not o['failures']
    assert o['latest_metrics']['epoch']+1==o['completed_epochs']
    assert all(p['same_live'] for p in o['processes'].values())
    refs[str(seed)]=o
    reftransport[str(seed)]={k:v for k,v in d.items() if k!='base64'}|{'file':f'compact_payload_seed{seed}_v9.json'}
    d=bundle['phase'][str(seed)]
    raw=base64.b64decode(d['base64'],validate=True)
    assert len(raw)==d['bytes'] and hashlib.sha256(raw).hexdigest()==d['sha256']
    o=json.loads(raw);assert o['seed']==seed
    phases[str(seed)]=o
    phasetransport[str(seed)]={k:v for k,v in d.items() if k!='base64'}|{'file':f'phase_payload_seed{seed}_v1.json'}
    a=o['arms']['original_stem'];b=o['arms']['native_stem_scratch']
    for k in ('transforms_policy','mosaic_prob','transform_names','collate_config','container_sha256','dataloader_sha256'):
        assert a[k]==b[k]
phasecode=ROOT/'\u82f1\u6587\u5c0f\u8bba\u6587/code/p2_candidate_seed1_full132_20261007_v1/engine/data'
assert sha(phasecode/'transforms/container.py')==phases['1']['arms']['original_stem']['container_sha256']
assert sha(phasecode/'dataloader.py')==phases['1']['arms']['original_stem']['dataloader_sha256']
pairs=[]
for seed in (1,2):
    r=refs[str(seed)];epoch=r['completed_epochs']
    rows=snap[f'seed{seed}']['jobs']['original_stem']['metrics']
    full=next(x for x in rows if x['epoch']+1==epoch)['test_coco_eval_bbox']
    native=r['latest_metrics']['test_coco_eval_bbox']
    pairs.append(dict(seed=seed,epoch=epoch,enhanced_AP=100*full[0],random_native_AP=100*native[0],
      delta_AP_pp=100*(full[0]-native[0]),enhanced_APs=100*full[3],random_native_APs=100*native[3],
      delta_APs_pp=100*(full[3]-native[3])))
primary=read(ROOT/'outputs/stem_primary_collection_20261011_v1/seed2_original_stem_v1/primary_verification_v1.json')
analysis=read(ROOT/'outputs/stem_primary_stage_analysis_20261011_v1/seed2_original_stem/report.json')
assert primary['all605_collected_files_verified'] and primary['actual_stage_images']==548
assert not primary['saved_EMA_independent_replay_verified'] and not analysis['causal_root_proven']
names=[REF/'compact_transport_v9.json',REF/'compact_observation_v9.json',REF/'execution_state_v7.json',
 MAIN/'same_epoch_random_native_comparison_v6.json',MAIN/'execution_state_v19.json',FULL/'execution_state_v22.json',
 PHASE/'transport_verification_v1.json',PHASE/'report.json']
names += [REF/f'compact_payload_seed{s}_v9.json' for s in (1,2)]
names += [PHASE/f'phase_payload_seed{s}_v1.json' for s in (1,2)]
assert not any(p.exists() for p in names)
PHASE.mkdir(parents=True,exist_ok=True)
for seed in (1,2):
    (REF/f'compact_payload_seed{seed}_v9.json').write_bytes(base64.b64decode(bundle['reference'][str(seed)]['base64'],validate=True))
    (PHASE/f'phase_payload_seed{seed}_v1.json').write_bytes(base64.b64decode(bundle['phase'][str(seed)]['base64'],validate=True))
write(REF/'compact_transport_v9.json',reftransport)
write(REF/'compact_observation_v9.json',refs)
write(PHASE/'transport_verification_v1.json',dict(status='PASS_BOTH_REMOTE_PAYLOAD_BYTE_LENGTH_SHA256_AND_LOCAL_SOURCE_SHA256',records=phasetransport))
phase_report=dict(status='VERIFIED_COMMON_TRAINING_POLICY_SOURCE_NOT_CAUSAL_PROOF',seeds=phases,
  first_four_human_epochs='Named stop_epoch policy transforms are skipped; Resize/RandomHorizontalFlip and other operations remain.',
  human_epoch5='Zero-based epoch4 permits Mosaic and the other named policy transforms; MixUp becomes eligible with probability0.5.',
  arms_policy_equal=True,new_model_forwards=0,new_evaluator_calls=0,new_optimizer_updates=0,
  source_code_sha256={'container.py':sha(phasecode/'transforms/container.py'),'dataloader.py':sha(phasecode/'dataloader.py')},
  causal_root_proven=False,scope='Verified shared recipe timing, not an experiment isolating the cause of metric changes.')
write(PHASE/'report.json',phase_report)
write(MAIN/'same_epoch_random_native_comparison_v6.json',dict(
 status='ANALYZED_DESCRIPTIVE_SAME_EPOCH_PER_SEED5_AND6',current_S_pairs=pairs,
 full_snapshot_sha256=sha(snapfile),random_native_observation_sha256=sha(REF/'compact_observation_v9.json'),
 all_seeds_preserved=True,fixed12_efficacy_established=False,root_cause_established=False,
 interpretation='Enhanced positive for seed2 at epoch6, negative for seed1 at epoch5; no cross-seed different-epoch average or fixed12 conclusion.',
 new_model_forwards=0,new_optimizer_updates=0))
refstate=copy.deepcopy(read(REF/'execution_state_v6.json'))
refstate.update(supersedes='execution_state_v6.json',evidence='compact_observation_v9.json',
 transport_verification='compact_transport_v9.json: exact SHA256 and byte length verified',
 user_steering='Compare the enhanced Stem with the random native Stem at the same epoch within each seed.',
 completed_epochs={k:v['completed_epochs'] for k,v in refs.items()},
 optimizer_updates={k:v['runtime']['training_audit_live.json']['actual_optimizer_steps'] for k,v in refs.items()},
 latest_live_processes={k:v['processes'] for k,v in refs.items()},
 processes={k:[dict(role=role,**p) for role,p in v['processes'].items()] for k,v in refs.items()})
write(REF/'execution_state_v7.json',refstate)
state=copy.deepcopy(read(MAIN/'execution_state_v18.json'))
state.update(supersedes='execution_state_v18.json',previous_goal_turn='progress',current_goal_turn='progress',
 no_progress_streak=0,goal_complete=False,
 user_steering='Compare enhancement against the same-epoch random original Stem without discarding either seed.',
 reference_state='../native_stem_scratch12_20261011_v3/execution_state_v7.json',
 evidence='training_observation_v25.json',baseline_comparison='progress_v25.json',
 latest_full_completed_epochs={f'seed{s}':len(snap[f'seed{s}']['jobs']['original_stem']['metrics']) for s in (1,2)},
 latest_active_control_completed_epochs={f'{a}_seed{s}':len(snap[f'seed{s}']['jobs'][a]['metrics']) for s in (1,2) for a in ('detail_lowres','highfreq_rgb')},
 new_reference_epochs={f'seed{s}':refs[str(s)]['completed_epochs'] for s in (1,2)},
 same_epoch_reference_comparison='same_epoch_random_native_comparison_v6.json',
 current_live_trainers={f'seed{s}':{a:snap[f'seed{s}']['jobs'][a]['processes'] for a in ('original_stem','detail_lowres','highfreq_rgb')} for s in (1,2)},
 live_observation_transport=dict(metadata='../stem_observation_file_transport_20261011_v1/observation_transport_v1.json',
 verification='training_observation_v25_transport_verification.json',status='PASS_BOTH_FILE_PAYLOAD_BYTE_LENGTH_AND_SHA256',
 scope='Large terminal snapshot downloaded as raw JSON instead of truncated PTY; observer source unchanged, training not restarted.'),
 latest_full_vs_same_epoch_pretrained_BASE='Enhanced seed1 completed10; seed2 exact12 AP7.908137290758578/APs5.160614737271937 below cached BASE12. Scratch comparison is positive seed2 epoch6 and negative seed1 epoch5.',
 finding='Downloaded and verified actual seed2 fixed12 last checkpoint and all548 stage records; real primary GT analysis found an initial selected-box coverage deficit. Independent saved-EMA replay and random-Stem fixed12 endpoints pending.',
 primary_seed2=dict(verification='../stem_primary_collection_20261011_v1/seed2_original_stem_v1/primary_verification_v1.json',
 analysis='../stem_primary_stage_analysis_20261011_v1/seed2_original_stem/report.json',
 checkpoint='../stem_primary_collection_20261011_v1/seed2_original_stem_v1/extracted/run/last.pth',
 last_checkpoint_sha256=primary['last_checkpoint_sha256'],actual_stage_images=548,saved_EMA_independent_replay_verified=False,
 AP=100*primary['native_stats'][0],APs=100*primary['native_stats'][3],causal_root_proven=False),
 training_phase_audit='../stem_training_phase_audit_20261011_v1/report.json',
 scientific_curve_snapshot='../stem_curves_20261011_v1/render_verification_v2.json',
 next='Finish current jobs at12, collect remaining actual primary packets, permit native coordinated closeouts, then run already prepared native selection diagnostics only when the actual GPU is idle.')
write(MAIN/'execution_state_v19.json',state)
fullstate=copy.deepcopy(read(FULL/'execution_state_v21.json'))
fullstate.update(supersedes='execution_state_v21.json',authoritative_state='../stem_component12_20261011_v1/execution_state_v19.json',
 reference_state='../native_stem_scratch12_20261011_v3/execution_state_v7.json')
write(FULL/'execution_state_v22.json',fullstate)
print(json.dumps(dict(status='PERSISTED_VERIFIED_CURRENT_COMPARISON_AND_ACTUAL_PRIMARY_EVIDENCE',pairs=pairs,
 full_completed=state['latest_full_completed_epochs'],reference_completed=state['new_reference_epochs'],
 main_state=str(MAIN/'execution_state_v19.json')),ensure_ascii=False))

